const e=JSON.parse('[{"id":"110_110010_001","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"工會會員大會或會員代表大會之決議內容違反法令或章程時，下列敘述何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"會員或會員代表得於決議後三十日內，訴請法院撤銷其決議","imageUrl":null},{"key":"B","text":"如其違反之事實非屬重大且於決議無影響者，報請主管機關調整並備查","imageUrl":null},{"key":"C","text":"申請不當勞動行為裁決撤銷之","imageUrl":null},{"key":"D","text":"無效","imageUrl":null}],"correctAnswer":"D","explanation":"工會法規定，工會會員大會或代表大會之決議內容違反法令或章程者，其決議為無效。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_002","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列何者非屬勞工保險門診給付範圍？","tableData":null,"images":[],"options":[{"key":"A","text":"勞保病房之供應","imageUrl":null},{"key":"B","text":"診察","imageUrl":null},{"key":"C","text":"藥劑或治療材料","imageUrl":null},{"key":"D","text":"處置、手術或治療","imageUrl":null}],"correctAnswer":"A","explanation":"門診給付範圍包括診察、藥劑、處置及手術等，病房供應則屬於住院給付範圍，非門診給付項目。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_003","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"依勞工保險條例之規定，投保單位申報被保險人投保薪資不實者，下列敘述何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"保險人得寬限十五日通知投保單位自行調整","imageUrl":null},{"key":"B","text":"保險人應通知投保單位自行調整並加徵投保薪資百分之二十上限之滯納金","imageUrl":null},{"key":"C","text":"由保險人按照同一行業相當等級之投保薪資額逕行調整通知投保單位","imageUrl":null},{"key":"D","text":"保險人應通知被保險人單獨辦理申報","imageUrl":null}],"correctAnswer":"C","explanation":"勞工保險條例規定，投保薪資不實者，保險人得按同一行業相當等級逕行調整並通知投保單位。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_004","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"甲向設於新北市之 A 公司應徵門市人員，A 公司以其容貌不佳為由拒絕僱用，甲認其涉及容貌歧視，應向下列何者提出申訴？","tableData":null,"images":[],"options":[{"key":"A","text":"新北市政府勞工局","imageUrl":null},{"key":"B","text":"勞動部勞動條件及就業平等司","imageUrl":null},{"key":"C","text":"勞動部性別工作平等會","imageUrl":null},{"key":"D","text":"行政院性別平等會","imageUrl":null}],"correctAnswer":"A","explanation":"就業歧視申訴應向勞務提供地之地方主管機關提出，甲於新北市求職，應向新北市政府勞工局申訴。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_005","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"依職工福利金條例之規定，下列何者非企業組織得就其一定比例提撥為職工福利金之來源？","tableData":null,"images":[],"options":[{"key":"A","text":"創立時之資本總額","imageUrl":null},{"key":"B","text":"每個職員工人每月之薪津","imageUrl":null},{"key":"C","text":"下腳變價","imageUrl":null},{"key":"D","text":"職工年終獎金或三節節金","imageUrl":null}],"correctAnswer":"D","explanation":"職工福利金來源包含創立資本額、每月薪津比例、營業收入及下腳變價，年終獎金非屬法定提撥來源。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_006","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"主管機關或檢查機構於接獲勞工對事業單位違反勞工法令規定之申訴後，應為必要之調查，並於幾日內將處理情形，以書面通知勞工？","tableData":null,"images":[],"options":[{"key":"A","text":"90 日","imageUrl":null},{"key":"B","text":"60 日","imageUrl":null},{"key":"C","text":"45 日","imageUrl":null},{"key":"D","text":"30 日","imageUrl":null}],"correctAnswer":"B","explanation":"依勞動基準法第 74 條規定，主管機關接獲申訴調查後，應於 60 日內以書面將處理情形通知勞工。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_007","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列關於雇主違反勞工退休金條例第 14 條第 1 項之規定，未按時提繳或繳足退休金之敘述，何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"按自僱用之日起至繳足退休金之前一日止之提繳標準，處四倍罰鍰","imageUrl":null},{"key":"B","text":"按自未提繳或繳足之日起至繳足退休金之前一日止之提繳標準，處二倍罰鍰","imageUrl":null},{"key":"C","text":"自期限屆滿之次日起至完繳前一日止，每逾一日加徵其應提繳金額百分之三滯納金至應提繳金額之一倍為止","imageUrl":null},{"key":"D","text":"勞工受有損害者，由勞動部勞工保險局與雇主連帶負損害賠償責任","imageUrl":null}],"correctAnswer":"C","explanation":"雇主逾期未提繳退休金，每逾一日加徵百分之三滯納金，至應提繳金額之一倍為止。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_008","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"雇主應為依勞工退休金條例第 7 條第 1 項規定之勞工，負擔提繳之退休金比率為何？","tableData":null,"images":[],"options":[{"key":"A","text":"不得高於勞工每月工資百分之六","imageUrl":null},{"key":"B","text":"不得低於勞工自願提繳退休金之比率","imageUrl":null},{"key":"C","text":"不得低於勞工每月工資百分之六","imageUrl":null},{"key":"D","text":"依勞工自願提繳退休金之比率定之","imageUrl":null}],"correctAnswer":"C","explanation":"勞工退休金條例第 14 條規定，雇主每月負擔之退休金提繳率，不得低於勞工每月工資百分之六。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_009","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"依勞動基準法第 39 條之規定，雇主經徵得勞工同意於休假日工作者，工資應加倍發給。本條所定休假日，不包含下列何者？","tableData":null,"images":[],"options":[{"key":"A","text":"內政部所定應放假之紀念日、節日","imageUrl":null},{"key":"B","text":"勞動節","imageUrl":null},{"key":"C","text":"特別休假","imageUrl":null},{"key":"D","text":"例假","imageUrl":null}],"correctAnswer":"D","explanation":"勞動基準法第 39 條之休假日包含紀念日、勞動節及特別休假，例假屬於第 36 條規定，不在此列。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_010","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列關於積欠工資墊償基金之敘述，何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"勞工依勞動基準法第 28 條第 1 項所列債權受償順序與第一順位抵押權、質權或留置權所擔保之債權相同","imageUrl":null},{"key":"B","text":"雇主一旦積欠勞工工資，勞工即得向積欠工資墊償基金請求墊償之","imageUrl":null},{"key":"C","text":"勞工本於勞動契約所積欠之工資全額，有最優先受清償之權","imageUrl":null},{"key":"D","text":"積欠工資墊償基金依規定墊償後，法院應定期限命雇主將墊款償還積欠工資墊償基金","imageUrl":null}],"correctAnswer":"A","explanation":"勞基法規定，積欠工資、退休金及資遣費之債權，與第一順位抵押權所擔保之債權受償順序相同。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_011","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"A 公司與員工間因加班費遲遲未發致生勞資爭議，該爭議屬於：","tableData":null,"images":[],"options":[{"key":"A","text":"調整事項之勞資爭議","imageUrl":null},{"key":"B","text":"調解事項之勞資爭議","imageUrl":null},{"key":"C","text":"權利事項之勞資爭議","imageUrl":null},{"key":"D","text":"勞資會議之勞資爭議","imageUrl":null}],"correctAnswer":"C","explanation":"加班費發放涉及法律或勞動契約規定權利之履行，故屬於權利事項之勞資爭議。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_012","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列何者，依勞資爭議處理法之規定，絕對不得罷工？","tableData":null,"images":[],"options":[{"key":"A","text":"自來水事業","imageUrl":null},{"key":"B","text":"電力及燃氣供應業","imageUrl":null},{"key":"C","text":"醫院","imageUrl":null},{"key":"D","text":"教師","imageUrl":null}],"correctAnswer":"D","explanation":"勞資爭議處理法第 54 條規定，教師、國防部及其所屬機關學校之勞工，絕對不得發動罷工。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_013","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"A 企業工會與其雇主進行多次團體協商，因雇主之協商代表對於部分條文屢次藉故拖延不談，A 工會得為下列何項救濟？","tableData":null,"images":[],"options":[{"key":"A","text":"依勞資爭議處理法申請不當勞動行為裁決","imageUrl":null},{"key":"B","text":"依勞動事件法提起勞動調解","imageUrl":null},{"key":"C","text":"依勞動事件法請求假處分","imageUrl":null},{"key":"D","text":"逕依勞資爭議處理法宣告罷工","imageUrl":null}],"correctAnswer":"A","explanation":"雇主無正當理由拒絕團體協商（包括拖延不談），屬不當勞動行為，勞方得申請裁決。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_014","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"甲為旅遊業員工，因嚴重特殊傳染性肺炎導致業務量受到衝擊，與雇主協商同意減班休息，並申請由政府提供部分薪資差額之補貼，我國行政機關負責此項業務政策之部門為何？","tableData":null,"images":[],"options":[{"key":"A","text":"勞動部勞動力發展署","imageUrl":null},{"key":"B","text":"勞動部勞動條件及就業平等司","imageUrl":null},{"key":"C","text":"交通部觀光局","imageUrl":null},{"key":"D","text":"衛生福利部社會救助及社工司","imageUrl":null}],"correctAnswer":"A","explanation":"勞動部勞動力發展署負責推動安心就業計畫等減班休息薪資補貼業務。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_015","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"勞動基準法第 9 條規定臨時性、短期性、季節性及特定性工作得為定期契約，請問其中何者期間得超過一年？","tableData":null,"images":[],"options":[{"key":"A","text":"臨時性工作","imageUrl":null},{"key":"B","text":"短期性工作","imageUrl":null},{"key":"C","text":"季節性工作","imageUrl":null},{"key":"D","text":"特定性工作","imageUrl":null}],"correctAnswer":"D","explanation":"勞動基準法施行細則規定，特定性工作係指可在特定期間完成之非繼續性工作，其期間得超過一年。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_016","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"對於調職的合法性判斷，雖我國學說與判決多以所謂的「調職五原則」進行判斷，但在民國 104 年修正勞動基準法時新增第 10 條之 1。除了將調職五原則立法化外，也增加了下列何者原先不屬於調職五原則之內容？","tableData":null,"images":[],"options":[{"key":"A","text":"不得違反勞動契約之約定","imageUrl":null},{"key":"B","text":"基於企業經營上所必須","imageUrl":null},{"key":"C","text":"調動工作地點過遠，雇主應予以必要之協助","imageUrl":null},{"key":"D","text":"考量勞工及其家庭之生活利益","imageUrl":null}],"correctAnswer":"D","explanation":"勞基法第 10 條之 1 第 5 款明確列入「考量勞工及其家庭之生活利益」，增加法律對勞工權益的保障。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_017","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"團體協約法第 6 條第 1 項所謂的拒絕團體協商之不當勞動行為，請問被課予團體協商義務之主體為：","tableData":null,"images":[],"options":[{"key":"A","text":"只有勞方","imageUrl":null},{"key":"B","text":"只有資方","imageUrl":null},{"key":"C","text":"勞資雙方均有團體協商義務","imageUrl":null},{"key":"D","text":"由主管機關決定","imageUrl":null}],"correctAnswer":"C","explanation":"團體協約法規定，勞資雙方應本誠實信用原則進行團體協商，雙方均負有協商義務。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_018","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列關於工會之論述，何者不符合我國工會法之規定？","tableData":null,"images":[],"options":[{"key":"A","text":"各級政府機關及公立學校公務人員之結社組織，依其他法律之規定","imageUrl":null},{"key":"B","text":"結合同一廠場、同一事業單位、依公司法所定具有控制與從屬關係之企業，或依金融控股公司法所定金融控股公司與子公司內之勞工所組織之各企業工會以組織一個為限","imageUrl":null},{"key":"C","text":"教師得組織及加入企業工會","imageUrl":null},{"key":"D","text":"組織工會應有勞工三十人以上之連署發起","imageUrl":null}],"correctAnswer":"C","explanation":"教師依規定雖得組織及加入工會，但限於組織產業工會及職業工會，不得組織企業工會。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_019","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"請問下列何者非屬就業服務法第 5 條第 1 項所規定之禁止就業歧視事由？","tableData":null,"images":[],"options":[{"key":"A","text":"星座","imageUrl":null},{"key":"B","text":"身心障礙","imageUrl":null},{"key":"C","text":"性傾向","imageUrl":null},{"key":"D","text":"現在之工會會員身分","imageUrl":null}],"correctAnswer":"D","explanation":"就業服務法禁止事由含星座、身障、性傾向等；工會會員身分之保護係規定於工會法第 35 條。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_020","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"就業服務法在 2018 年增訂了第 5 條第 2 項第 6 款，規定雇主提供職缺之經常性薪資未達新臺幣多少元時，必須公開揭示或告知其薪資範圍，否則依同法第 67 條第 1 項得處以新臺幣六萬元以上三十萬元以下罰鍰？","tableData":null,"images":[],"options":[{"key":"A","text":"新臺幣三萬元","imageUrl":null},{"key":"B","text":"新臺幣三萬五千元","imageUrl":null},{"key":"C","text":"新臺幣四萬元","imageUrl":null},{"key":"D","text":"新臺幣四萬五千元","imageUrl":null}],"correctAnswer":"C","explanation":"就業服務法規定，招募職缺經常性薪資未達新臺幣四萬元者，雇主應公開揭示其薪資範圍。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_021","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"依勞動基準法第 38 條第 1 項之規定，勞工在同一雇主繼續工作六個月以上一年未滿時，有幾日之特別休假？","tableData":null,"images":[],"options":[{"key":"A","text":"1 日","imageUrl":null},{"key":"B","text":"2 日","imageUrl":null},{"key":"C","text":"3 日","imageUrl":null},{"key":"D","text":"4 日","imageUrl":null}],"correctAnswer":"C","explanation":"勞基法規定，勞工在同一雇主繼續工作六個月以上一年未滿者，應給予特別休假三日。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_022","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"依勞動基準法第 84 條之 1 第 1 項，下列何者在經中央主管機關核定公告並報請當地主管機關核備後，得由勞雇雙方另行約定工作時間、例假、休假、女性夜間工作，而不受同法第 30 條、第 32 條、第 36 條、第 37 條、第 49 條之限制？","tableData":null,"images":[],"options":[{"key":"A","text":"監視性工作","imageUrl":null},{"key":"B","text":"臨時性工作","imageUrl":null},{"key":"C","text":"短期性工作","imageUrl":null},{"key":"D","text":"季節性工作","imageUrl":null}],"correctAnswer":"A","explanation":"經核定之監視性、責任制或特殊性質工作，勞雇雙方可另行約定工時，不受一般法定工時限制。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_023","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"工會法、團體協約法與勞資爭議處理法均為保護勞工「勞動三權」之立法，請問下列何者非屬勞動三權之內容？","tableData":null,"images":[],"options":[{"key":"A","text":"團結權","imageUrl":null},{"key":"B","text":"工作權","imageUrl":null},{"key":"C","text":"集體協商權","imageUrl":null},{"key":"D","text":"爭議權","imageUrl":null}],"correctAnswer":"B","explanation":"勞動三權是指保護勞工集體行動之團結權、集體協商權（交涉權）及爭議權，不包含工作權。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_024","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"勞動基準法所規定的變形工時制度中，何者不須每七日中至少有一日例假？","tableData":null,"images":[],"options":[{"key":"A","text":"二週變形工時制度","imageUrl":null},{"key":"B","text":"四週變形工時制度","imageUrl":null},{"key":"C","text":"八週變形工時制度","imageUrl":null},{"key":"D","text":"所有變形工時制度均須每七日中至少有一日例假","imageUrl":null}],"correctAnswer":"B","explanation":"勞基法規定，四週變形工時制度下，勞工每二週內應有二日例假，放寬了每七日一休之限制。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_025","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列有關禁止性騷擾之論述，何者不符合性別工作平等法之規定？","tableData":null,"images":[],"options":[{"key":"A","text":"實習生於實習期間遭受性騷擾時，不適用性別工作平等法之規定","imageUrl":null},{"key":"B","text":"雇主對受僱者或求職者為明示或暗示之性要求，作為成立勞務契約之交換條件亦屬性騷擾","imageUrl":null},{"key":"C","text":"僱用受僱者三十人以上之雇主，應訂定性騷擾防治措施、申訴及懲戒辦法，並在工作場所公開揭示","imageUrl":null},{"key":"D","text":"受僱者或求職者因性騷擾致受有損害時，由雇主及行為人連帶負損害賠償責任。若由雇主賠償損害時，對於為性騷擾之行為人，雇主有求償權","imageUrl":null}],"correctAnswer":"A","explanation":"性別工作平等法明確規定，實習生於實習期間遭受性騷擾時，亦適用該法之相關規範及保障。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_026","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"勞動派遣是我國極為普遍的非典型勞動方式，不過直至 2019 年勞動基準法修正時才對之有所規範。請問下列論述何者不符合我國勞動基準法之規定？","tableData":null,"images":[],"options":[{"key":"A","text":"派遣事業單位得與派遣勞工訂定定期勞動契約","imageUrl":null},{"key":"B","text":"要派單位不得於派遣事業單位與派遣勞工簽訂勞動契約前，有面試該派遣勞工或其他指定特定派遣勞工之行為","imageUrl":null},{"key":"C","text":"派遣事業單位積欠派遣勞工工資，經主管機關處罰時，派遣勞工得請求要派單位給付","imageUrl":null},{"key":"D","text":"要派單位使用派遣勞工發生職業災害時，要派單位應與派遣事業單位連帶負勞動基準法所定雇主應負職業災害補償之責任","imageUrl":null}],"correctAnswer":"A","explanation":"勞動基準法第 9 條規定，派遣事業單位與派遣勞工訂定之勞動契約，應為不定期契約。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_027","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列敘述何者不符合勞動基準法及其施行細則對於離職後競業禁止約定之規定？","tableData":null,"images":[],"options":[{"key":"A","text":"雇主有應受保護之正當營業利益時，始得與勞工為離職後競業禁止之約定","imageUrl":null},{"key":"B","text":"縱使勞工擔任之職位或職務無法接觸或使用雇主之營業秘密，但為了企業之利益，仍得與勞工為有效之離職後競業禁止約定","imageUrl":null},{"key":"C","text":"離職後競業禁止之期間，最長不得逾二年","imageUrl":null},{"key":"D","text":"雇主對勞工因不從事競業行為所受損失有合理補償，且每月補償金額不低於勞工離職時一個月平均工資百分之五十","imageUrl":null}],"correctAnswer":"B","explanation":"離職後競業禁止之約定，必須以勞工職務能接觸或使用雇主之營業秘密為必要前提。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_028","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列何種工會不問其會員受僱於協商他方之人數，在協商他方有不誠信協商之情事時，均具有團體協商資格而得向裁決委員會申請不當勞動行為裁決？","tableData":null,"images":[],"options":[{"key":"A","text":"企業工會","imageUrl":null},{"key":"B","text":"產業工會","imageUrl":null},{"key":"C","text":"職業工會","imageUrl":null},{"key":"D","text":"綜合性工會","imageUrl":null}],"correctAnswer":"A","explanation":"企業工會依團體協約法規定，具有法定的團體協商資格，不論受僱人數多寡皆可申請不誠信協商裁決。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_029","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列何者非屬直轄市、縣（市）主管機關得為之事項？","tableData":null,"images":[],"options":[{"key":"A","text":"設置職業疾病認定委員會","imageUrl":null},{"key":"B","text":"設置性別工作平等會","imageUrl":null},{"key":"C","text":"依勞動基準法第 34 條第 2 項公告變更輪班更換班次之休息時間不少於連續 8 小時","imageUrl":null},{"key":"D","text":"派員實施勞動檢查","imageUrl":null}],"correctAnswer":"C","explanation":"變更輪班更換班次之休息時間之核定與公告，屬於中央主管機關（勞動部）之職權，非地方主管機關。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_030","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"在勞動部中職掌「大量解僱勞工保護政策、法規與計畫之研析、規劃及協調」之單位為：","tableData":null,"images":[],"options":[{"key":"A","text":"勞動法務司","imageUrl":null},{"key":"B","text":"勞動條件及就業平等司","imageUrl":null},{"key":"C","text":"勞動福祉退休司","imageUrl":null},{"key":"D","text":"勞動關係司","imageUrl":null}],"correctAnswer":"D","explanation":"勞動關係司負責掌理勞資關係、團體協約及大量解僱勞工保護等相關政策與法規之規劃。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_031","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列何者非團體協約所得約定之事項？","tableData":null,"images":[],"options":[{"key":"A","text":"工會之組織","imageUrl":null},{"key":"B","text":"參與企業經營組織","imageUrl":null},{"key":"C","text":"限制雇主採用新機器","imageUrl":null},{"key":"D","text":"團體協約之協商程序","imageUrl":null}],"correctAnswer":"D","explanation":"團體協約約定事項包含勞動條件、工會組織及企業經營等；協商程序屬於進行協商時之程序規範。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_032","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"對於裁決委員會基於工會法第 35 條第 2 項所為的裁決決定，當事人不服時應向法院提起如何之訴訟？","tableData":null,"images":[],"options":[{"key":"A","text":"民事訴訟","imageUrl":null},{"key":"B","text":"刑事訴訟","imageUrl":null},{"key":"C","text":"行政訴訟","imageUrl":null},{"key":"D","text":"憲法訴訟","imageUrl":null}],"correctAnswer":"C","explanation":"不當勞動行為裁決決定書之性質為行政處分，當事人若有不服，應依行政訴訟法提起行政訴訟。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_033","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"工會之最高權力機關為何？","tableData":null,"images":[],"options":[{"key":"A","text":"理事長","imageUrl":null},{"key":"B","text":"理事","imageUrl":null},{"key":"C","text":"監事","imageUrl":null},{"key":"D","text":"工會會員大會","imageUrl":null}],"correctAnswer":"D","explanation":"工會法規定，工會以會員大會或會員代表大會為其最高權力機關。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_034","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"勞資爭議在調解、仲裁或裁決期間，資方得採取下列何種行為？","tableData":null,"images":[],"options":[{"key":"A","text":"因該勞資爭議事件而停工","imageUrl":null},{"key":"B","text":"因該勞資爭議事件而單方終止勞動契約","imageUrl":null},{"key":"C","text":"因該勞資爭議事件而懲戒相關之勞工","imageUrl":null},{"key":"D","text":"因該勞資爭議事件而與相關的勞工合意終止勞動契約","imageUrl":null}],"correctAnswer":"D","explanation":"法律禁止雇主在調解期間因爭議事件而單方終止契約，但若與勞工達成「合意」終止契約則不在此限。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_035","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列關於工會會務假之論述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"所謂工會之會務，包括了從事或參與由主管機關或目的事業主管機關指定、舉辦與勞動事務或會務有關之活動或集會","imageUrl":null},{"key":"B","text":"企業工會與雇主間無特別約定時，其理事長得以半日或全日，請公假辦理會務","imageUrl":null},{"key":"C","text":"企業工會與雇主間無特別約定時，其監事得於每月五十小時之範圍內，請公假辦理會務","imageUrl":null},{"key":"D","text":"對於工會理事長或其他理事、監事的會務假申請，雇主即應照准","imageUrl":null}],"correctAnswer":"D","explanation":"雇主應准許法定的會務公假，但若申請不符工會法規定之會務範圍，雇主得不予照准。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_036","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列有關禁止性別歧視之論述，何者不符合性別工作平等法之規定？","tableData":null,"images":[],"options":[{"key":"A","text":"雇主對求職者或受僱者之招募不得因性別或性傾向而有差別待遇，但工作性質僅適合特定性別者，不在此限","imageUrl":null},{"key":"B","text":"工作規則、勞動契約或團體協約若規定或事先約定受僱者有結婚、懷孕、分娩或育兒之情事時，應行離職或留職停薪，該規定或約定之效力未定","imageUrl":null},{"key":"C","text":"雇主對受僱者薪資之給付得基於年資、獎懲、績效或其他非因性別或性傾向因素之正當理由而為差別待遇","imageUrl":null},{"key":"D","text":"雇主為受僱者舉辦或提供各項福利措施，不得因性別或性傾向而有差別待遇","imageUrl":null}],"correctAnswer":"B","explanation":"性別工作平等法規定，事先約定受僱者結婚或懷孕即應離職之效力為無效，而非效力未定。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_037","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"受僱者於其配偶分娩時，依性別工作平等法之規定，雇主應給予幾日之陪產假？","tableData":null,"images":[],"options":[{"key":"A","text":"3 日","imageUrl":null},{"key":"B","text":"5 日","imageUrl":null},{"key":"C","text":"7 日","imageUrl":null},{"key":"D","text":"10 日","imageUrl":null}],"correctAnswer":"B","explanation":"依據性別工作平等法之規定，受僱者於其配偶分娩時，雇主應給予五日之陪產假。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_038","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"職業訓練法中所規定的職業訓練之實施，不包括下列何者？","tableData":null,"images":[],"options":[{"key":"A","text":"身心障礙者訓練","imageUrl":null},{"key":"B","text":"養成訓練","imageUrl":null},{"key":"C","text":"進修訓練","imageUrl":null},{"key":"D","text":"轉業訓練","imageUrl":null}],"correctAnswer":"A","explanation":"職業訓練法明定職業訓練實施項目包含養成訓練、進修訓練及轉業訓練，不含身心障礙者訓練。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_039","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列何者非屬職工福利金條例中對於職工福利金之保障規定？","tableData":null,"images":[],"options":[{"key":"A","text":"職工福利金不得沒收","imageUrl":null},{"key":"B","text":"職工福利金有優先受清償之權","imageUrl":null},{"key":"C","text":"因保管人之過失致職工福利金受損失時，應由提撥者負賠償責任","imageUrl":null},{"key":"D","text":"工廠、礦場或其他企業組織因解散或受破產宣告而結束經營者，所提撥之職工福利金，應由職工福利委員會妥議處理方式，陳報主管官署備查後發給職工","imageUrl":null}],"correctAnswer":"C","explanation":"職工福利金條例規定，因保管人過失致福利金受損時，應由該保管人負責賠償。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_040","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"私立學校、團體及民營事業機構員工總人數在多少人以上時，必須進用具有就業能力之身心障礙者人數，不得低於員工總人數百分之一且不得少於一人，否則應定期向所在地直轄市、縣（市）勞工主管機關之身心障礙者就業基金繳納差額補助費？","tableData":null,"images":[],"options":[{"key":"A","text":"34 人","imageUrl":null},{"key":"B","text":"50 人","imageUrl":null},{"key":"C","text":"67 人","imageUrl":null},{"key":"D","text":"100 人","imageUrl":null}],"correctAnswer":"C","explanation":"身心障礙者權益保障法規定，民營事業單位員工總人數達 67 人以上者，應進用身心障礙者。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_041","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"依就業服務法第 34 條之規定，對於私立就業機關的設立係採取下列何者？","tableData":null,"images":[],"options":[{"key":"A","text":"許可原則","imageUrl":null},{"key":"B","text":"準則原則","imageUrl":null},{"key":"C","text":"特許原則","imageUrl":null},{"key":"D","text":"強制原則","imageUrl":null}],"correctAnswer":"A","explanation":"依據就業服務法第 34 條規定，私立就業服務機構之設立應經主管機關之許可。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_042","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"從事家庭幫傭及看護工作之外國人，在我國境內工作期間累計不得逾多久？","tableData":null,"images":[],"options":[{"key":"A","text":"9 年","imageUrl":null},{"key":"B","text":"10 年","imageUrl":null},{"key":"C","text":"12 年","imageUrl":null},{"key":"D","text":"15 年","imageUrl":null}],"correctAnswer":"C","explanation":"就業服務法規定，從事家庭幫傭或看護工作之外國人，其在台累計工作年限不得超過十二年。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_043","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"受聘僱之外國人有連續曠職三日失去聯繫或聘僱關係終止之情事，雇主應於幾日內以書面載明相關事項通知當地主管機關、入出國管理機關及警察機關？","tableData":null,"images":[],"options":[{"key":"A","text":"3 日","imageUrl":null},{"key":"B","text":"5 日","imageUrl":null},{"key":"C","text":"7 日","imageUrl":null},{"key":"D","text":"10 日","imageUrl":null}],"correctAnswer":"A","explanation":"依就業服務法第 56 條規定，外國人曠職失去聯繫時，雇主應於三日內書面通知相關主管機關。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_044","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列何者非屬得自願參加勞工保險之人員？","tableData":null,"images":[],"options":[{"key":"A","text":"無一定雇主或自營作業而參加職業工會者","imageUrl":null},{"key":"B","text":"受僱於僱用未滿五人之公司、行號之員工","imageUrl":null},{"key":"C","text":"實際從事勞動之雇主","imageUrl":null},{"key":"D","text":"參加勞工保險，年資合計滿十五年，被裁減資遣者","imageUrl":null}],"correctAnswer":"A","explanation":"參加職業工會之無一定雇主或自營作業者，屬於勞工保險之強制投保對象，非自願參加人員。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_045","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"得請領勞工保險老年年金給付之被保險人為年滿六十歲以上並有幾年之保險年資者？","tableData":null,"images":[],"options":[{"key":"A","text":"10 年","imageUrl":null},{"key":"B","text":"15 年","imageUrl":null},{"key":"C","text":"20 年","imageUrl":null},{"key":"D","text":"25 年","imageUrl":null}],"correctAnswer":"B","explanation":"勞工保險條例規定，請領老年年金給付之條件為年滿 60 歲且保險年資合計滿 15 年。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_046","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"下列何者非屬視為職業傷害之情形？","tableData":null,"images":[],"options":[{"key":"A","text":"被保險人於工作時間中基於生理需要於如廁或飲水時發生事故而致之傷害","imageUrl":null},{"key":"B","text":"被保險人上、下班，於適當時間，從日常居、住處所往返就業場所之應經途中發生事故而致之傷害","imageUrl":null},{"key":"C","text":"被保險人於執行職務時，因天然災害直接發生事故導致之傷害，且其從事之業務非屬遭受天然災害之危險性較高者","imageUrl":null},{"key":"D","text":"被保險人因執行職務受動物或植物傷害","imageUrl":null}],"correctAnswer":"C","explanation":"若被保險人從事之業務非屬天然災害危險性較高者，其因天災受傷不視為職業傷害。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_047","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"依職業災害勞工保護法之規定，下列何種情形，雇主不得預告終止與職業災害勞工之勞動契約？","tableData":null,"images":[],"options":[{"key":"A","text":"歇業或重大虧損，報經主管機關核定","imageUrl":null},{"key":"B","text":"業務緊縮","imageUrl":null},{"key":"C","text":"因天災、事變或其他不可抗力因素，致事業不能繼續經營，報經主管機關核定","imageUrl":null},{"key":"D","text":"職業災害勞工經醫療終止後，經公立醫療機構認定身心障礙不堪勝任工作","imageUrl":null}],"correctAnswer":"B","explanation":"職業災害勞工保護法規定，職災勞工醫療期間，雇主不得以業務緊縮為由預告終止勞動契約。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_048","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"適用勞工退休金條例之勞工因不能勝任工作而被解僱時，對於其適用該條例後的工作年資所計算之資遣費，最高以發給多少個月的平均工資為限？","tableData":null,"images":[],"options":[{"key":"A","text":"3 個月","imageUrl":null},{"key":"B","text":"6 個月","imageUrl":null},{"key":"C","text":"9 個月","imageUrl":null},{"key":"D","text":"12 個月","imageUrl":null}],"correctAnswer":"B","explanation":"勞退新制規定，資遣費每滿一年發給半個月平均工資，最高以發給六個月為限。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_049","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"適用勞工退休金條例之勞工得請領月退休金之要件為：","tableData":null,"images":[],"options":[{"key":"A","text":"只要勞工年滿 65 歲即可","imageUrl":null},{"key":"B","text":"勞工年滿 65 歲，且工作年資滿 10 年以上","imageUrl":null},{"key":"C","text":"只要勞工工作年資滿 20 年以上即可","imageUrl":null},{"key":"D","text":"勞工年滿 60 歲，且工作年資滿 15 年以上","imageUrl":null}],"correctAnswer":"D","explanation":"勞工退休金條例第 24 條規定，勞工年滿 60 歲，且工作年資滿 15 年以上者，得請領月退休金。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_050","category":"chinese","stageId":"110_110010_503","type":"multiple-choice","difficulty":2,"text":"勞動基準法第 11 條所規定之雇主得預告勞工終止勞動契約的事由不包括下列何者？","tableData":null,"images":[],"options":[{"key":"A","text":"歇業","imageUrl":null},{"key":"B","text":"轉讓","imageUrl":null},{"key":"C","text":"改組","imageUrl":null},{"key":"D","text":"不可抗力暫停工作在一個月以上時","imageUrl":null}],"correctAnswer":"C","explanation":"勞動基準法第 11 條列舉之事由包含歇業、轉讓及不可抗力停工等，並不包含企業改組。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","503","勞工行政","勞工行政與勞工法規大意","測驗題"],"certificationType":"110年公務人員初等考試"}]');export{e as default};
